"use client";

import { services } from "@/data/services";
import { Check, Clock, Tag, ArrowRight } from "lucide-react";
import Link from "next/link";
import { motion } from "framer-motion";
import { cn } from "@/lib/utils";
import FinalCTA from "@/components/sections/FinalCTA";

export default function ServicesPage() {
  return (
    <div className="pt-36 md:pt-44 pb-16 md:pb-24">
      {/* Header */}
      <section className="px-6 mb-16 md:mb-24">
        <div className="max-w-7xl mx-auto text-center">
          <motion.p
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.4 }}
            className="text-primary text-sm font-bold uppercase tracking-[0.3em] mb-4"
          >
            Our Offerings
          </motion.p>
          <motion.h1
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.1 }}
            className="text-5xl md:text-7xl font-black text-foreground mb-8 font-outfit"
          >
            Digital Engineering <br />
            <span className="text-gradient">Redefined.</span>
          </motion.h1>
          <motion.p
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.15 }}
            className="text-foreground/60 text-lg md:text-xl max-w-2xl mx-auto leading-relaxed"
          >
            We deliver high-performance solutions tailored for growth and scale.
            Every service is backed by our expert collective of senior engineers.
          </motion.p>

          {/* Quick nav pills */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.5, delay: 0.25 }}
            className="flex flex-wrap justify-center gap-3 mt-10"
          >
            {services.map((s) => (
              <Link
                key={s.id}
                href={`#${s.id}`}
                className="px-4 py-2 rounded-full border border-border hover:border-primary/50 text-xs font-semibold text-foreground/60 hover:text-primary transition-all"
              >
                {s.title}
              </Link>
            ))}
          </motion.div>
        </div>
      </section>

      {/* Services List */}
      <section className="px-6 space-y-24 md:space-y-32">
        {services.map((service, index) => (
          <motion.div
            key={service.id}
            id={service.id}
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, margin: "-80px" }}
            transition={{ duration: 0.5 }}
            className="max-w-7xl mx-auto"
          >
            <div className={`grid grid-cols-1 lg:grid-cols-2 gap-16 items-center`}>
              {/* Text side */}
              <div className={index % 2 !== 0 ? "lg:order-2" : ""}>
                <div className="inline-flex items-center gap-2 px-4 py-2 bg-primary/10 border border-primary/20 rounded-full text-primary text-xs font-bold uppercase tracking-widest mb-6">
                  <service.icon className="w-3.5 h-3.5" />
                  {service.title}
                </div>
                <h2 className="text-4xl md:text-5xl font-bold text-foreground mb-6 font-outfit">
                  {service.title}
                </h2>
                <p className="text-foreground/70 text-lg leading-relaxed mb-10">
                  {service.description}
                </p>

                {/* Feature grid */}
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-3.5 mb-12">
                  {service.features.map((feature) => (
                    <div key={feature} className="flex items-start gap-3">
                      <div className="w-5 h-5 bg-primary/15 rounded-full flex items-center justify-center shrink-0 mt-0.5">
                        <Check className="w-3 h-3 text-primary" />
                      </div>
                      <span className="text-foreground/80 text-sm font-medium">{feature}</span>
                    </div>
                  ))}
                </div>

                {/* Pricing / Timeline / CTA */}
                <div className="flex flex-wrap gap-6 items-center border-t border-border/50 pt-8">
                  <div className="flex items-center gap-2.5">
                    <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center">
                      <Tag className="w-4 h-4 text-primary" />
                    </div>
                    <div>
                      <p className="text-[10px] uppercase text-foreground/40 tracking-wider">Investment</p>
                      <p className="text-foreground font-bold text-sm">{service.pricingHint}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2.5">
                    <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center">
                      <Clock className="w-4 h-4 text-primary" />
                    </div>
                    <div>
                      <p className="text-[10px] uppercase text-foreground/40 tracking-wider">Timeline</p>
                      <p className="text-foreground font-bold text-sm">{service.timeline}</p>
                    </div>
                  </div>
                  <Link
                    href={`/services/${service.id}`}
                    className="ml-auto inline-flex items-center gap-2 px-6 py-3 bg-primary text-white rounded-xl font-semibold text-sm hover:bg-primary/90 hover:scale-105 transition-all"
                  >
                    View Details <ArrowRight className="w-4 h-4" />
                  </Link>
                </div>
              </div>

              {/* Visual side */}
              <div className={cn("relative", index % 2 !== 0 ? "lg:order-1" : "")}>
                <div className={cn("aspect-square rounded-[3rem] overflow-hidden border border-border/60 relative group", "bg-gradient-to-br", service.color)}>
                  {/* Animated glow */}
                  <div className={cn("absolute inset-0 transition-opacity duration-500 group-hover:opacity-100 opacity-60", service.glow)} />
                  <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-32 h-32 bg-primary/30 blur-[80px] rounded-full group-hover:w-56 group-hover:h-56 transition-all duration-700" />

                  {/* Center icon + label */}
                  <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <div className="w-20 h-20 rounded-2xl bg-white/10 backdrop-blur-sm border border-white/20 flex items-center justify-center mb-4 group-hover:scale-110 transition-transform duration-500">
                      <service.icon className="w-10 h-10 text-white/70" />
                    </div>
                    <h4 className="text-white/30 text-2xl font-black uppercase tracking-[0.15em] text-center px-8">
                      {service.title}
                    </h4>
                  </div>

                  {/* Corner feature tags */}
                  <div className="absolute bottom-6 left-6 right-6 flex flex-wrap gap-2">
                    {service.features.slice(0, 2).map((f) => (
                      <span key={f} className="text-[10px] font-bold bg-black/30 backdrop-blur-sm text-white/60 rounded-full px-3 py-1">
                        {f}
                      </span>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </motion.div>
        ))}
      </section>

      <FinalCTA />
    </div>
  );
}
